.bcn-mkt-nav {
  z-index: 100;
  block-size: 56px;
  padding-inline: var(--spacing-500);
  border-radius: var(--radius-200);
  background: #ffffff0d;
  border: 1px solid #ffffff1a;
  justify-content: space-between;
  align-items: center;
  display: flex;
  position: absolute;
  top: 16px;
  left: 16px;
  right: 16px;
}
.bcn-mkt-nav__logo {
  align-items: center;
  gap: var(--spacing-250);
  text-decoration: none;
  display: flex;
}
.bcn-mkt-nav__logo svg {
  block-size: 32px;
  inline-size: 22px;
}
.bcn-mkt-nav__wordmark {
  font-size: 1.1rem;
  font-weight: var(--typography-font-weight-bold);
  letter-spacing: -0.02em;
  color: #fff;
}
.bcn-mkt-nav__login {
  padding: var(--spacing-150) var(--spacing-400);
  font-size: var(--font-size-200);
  font-weight: var(--typography-font-weight-medium);
  color: #fff;
  border-radius: var(--radius-100);
  background: 0 0;
  border: 1px solid #fff6;
  align-items: center;
  text-decoration: none;
  transition:
    background 0.15s,
    border-color 0.15s;
  display: inline-flex;
}
.bcn-mkt-nav__login:hover {
  background: #ffffff1a;
  border-color: #fff;
}

.bcn-mkt-hero {
  background-image:
    linear-gradient(180deg, #002832d9 0%, #003c46b3 40%, #005862d9 100%), var(--_hero-image);
  background-position: 50% 30%;
  background-size: cover;
  padding: 120px 0 96px;
  position: relative;
  overflow: hidden;
}
.bcn-mkt-hero__inner {
  max-inline-size: 1600px;
  padding-inline: var(--spacing-500);
  text-align: center;
  z-index: 1;
  margin-inline: auto;
  position: relative;
}
.bcn-mkt-hero__headline {
  margin: 0 0 var(--spacing-500);
  font-family: var(--font-decorative, var(--typography-font-family-sans));
  font-size: var(--font-size-800);
  font-weight: var(--typography-font-weight-bold);
  color: #fff;
  line-height: 1.15;
}
.bcn-mkt-hero__sub {
  margin: 0 auto var(--spacing-600);
  max-inline-size: 840px;
  font-size: var(--font-size-400);
  font-weight: var(--typography-font-weight-medium);
  color: #ffffffd9;
  text-wrap: pretty;
  line-height: normal;
}
.bcn-mkt-hero__ctas {
  gap: var(--spacing-300);
  flex-wrap: wrap;
  justify-content: center;
  display: flex;
}
.bcn-mkt-hero__btn {
  align-items: center;
  gap: var(--spacing-200);
  padding: var(--spacing-400) var(--spacing-600);
  font-family: inherit;
  font-size: var(--font-size-300);
  font-weight: var(--typography-font-weight-semibold);
  border-radius: var(--radius-200);
  cursor: pointer;
  border: 1px solid #0000;
  text-decoration: none;
  transition:
    background 0.15s,
    border-color 0.15s;
  display: inline-flex;
}
.bcn-mkt-hero__btn--white {
  color: var(--color-background-brand);
  background: #fff;
  border-color: #fff;
}
.bcn-mkt-hero__btn--white:hover {
  background: var(--color-background-elevation-sunken, #fafafa);
}
.bcn-mkt-hero__badge {
  align-items: center;
  gap: var(--spacing-200);
  font-size: var(--font-size-150);
  color: #fff9;
  margin-block-start: var(--spacing-700);
  display: inline-flex;
}
[data-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}
.esa-icon {
  --_icon-size: var(--icon-size-md, 20px);
  width: var(--_icon-size);
  height: var(--_icon-size);
  color: inherit;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, 16px);
}
.esa-icon svg {
  width: var(--_icon-size);
  height: var(--_icon-size);
  display: block;
}

.bcn-section-intro {
  margin-block-end: var(--spacing-700);
}
.bcn-section-intro__eyebrow {
  font-size: 12px;
  font-weight: var(--typography-font-weight-semibold);
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--color-content-default-tertiary);
  margin-block-end: var(--spacing-300);
  display: block;
}
.bcn-section-intro__headline {
  margin: 0 0 var(--spacing-400);
  font-family: var(--font-decorative, var(--typography-font-family-sans));
  font-size: var(--font-size-700);
  font-weight: var(--typography-font-weight-bold);
  line-height: var(--line-height-tight, 1.25);
  color: var(--color-content-default);
  text-wrap: balance;
}
.bcn-section-intro__accent {
  background: var(--color-background-brand);
  border-radius: var(--radius-full, 9999px);
  block-size: 4px;
  inline-size: 48px;
  margin-block-end: var(--spacing-400);
}
.bcn-section-intro--center .bcn-section-intro__accent {
  margin-inline: auto;
}
.bcn-section-intro__subtext {
  font-size: var(--font-size-300);
  color: var(--color-content-default-secondary);
  max-inline-size: 820px;
  line-height: var(--line-height-relaxed, 1.75);
  text-wrap: balance;
  margin: 0;
}
.bcn-section-intro--center .bcn-section-intro__subtext {
  margin-inline: auto;
}
.bcn-section-intro--on-dark .bcn-section-intro__eyebrow {
  color: #fff9;
}
.bcn-section-intro--on-dark .bcn-section-intro__headline {
  color: #fff;
}
.bcn-section-intro--on-dark .bcn-section-intro__accent {
  background: #fff;
}
.bcn-section-intro--on-dark .bcn-section-intro__subtext {
  color: #fffc;
}
.bcn-mkt-section {
  --_section-pad: clamp(48px, 8vw, 96px);
  padding-block: var(--_section-pad);
}
.bcn-mkt-section--white {
  background: var(--color-background-elevation-raised);
}
.bcn-mkt-section__inner {
  max-inline-size: 1100px;
  padding-inline: var(--spacing-500);
  margin-inline: auto;
}
[data-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}
.bcn-scale {
  gap: var(--spacing-700);
  grid-template-columns: 1fr 1fr;
  align-items: center;
  display: grid;
}
.bcn-scale__stats {
  gap: var(--spacing-500);
  grid-template-columns: 1fr 1fr;
  display: grid;
}
.bcn-scale__stat {
  align-items: flex-start;
  gap: var(--spacing-400);
  display: flex;
}
.bcn-scale__icon {
  color: var(--color-background-brand);
  flex-shrink: 0;
  margin-block-start: 2px;
  display: inline-flex;
}
.bcn-scale__value {
  font-family: var(--font-decorative, var(--typography-font-family-sans));
  font-size: var(--font-size-500);
  font-weight: var(--typography-font-weight-bold);
  color: var(--color-content-default);
  margin-block-end: var(--spacing-100);
  line-height: 1;
}
.bcn-scale__label {
  font-size: var(--font-size-150);
  color: var(--color-content-default-secondary);
  line-height: var(--line-height-normal, 1.5);
}
.bcn-scale__image {
  border-radius: var(--radius-200);
  overflow: hidden;
}
.bcn-scale__image img {
  object-fit: cover;
  block-size: 100%;
  min-block-size: 400px;
  inline-size: 100%;
}
@media (width<=768px) {
  .bcn-scale {
    grid-template-columns: 1fr;
  }
}
@media (width<=768px) {
  .bcn-scale__image {
    display: none;
  }
}
@media (width<=768px) {
  .bcn-scale__stats {
    grid-template-columns: 1fr;
  }
}
